const colors = { high: "#168366", medium: "#4d78ac", low: "#d59c43", line: "#167d68", muted: "#788d98" };
const groups = ["High", "Medium", "Low"] as const;
type PurchaseActivity = { name: string; total: number; zero: number; withPurchases: number; unavailable: number };

function purchaseActivityExplanation(row: PurchaseActivity, measure: "total" | "zero" | "withPurchases" | "unavailable" | "share", referenceDate: string | null): ResultExplanation {
  const scope = `${row.name} Priority accounts matching the current filters, as saved for the analysis reference date ${referenceDate ?? "unavailable"}.`;
  const counts = `${row.zero} with zero, ${row.withPurchases} with at least one, and ${row.unavailable} with an unavailable count.`;
  if (measure === "total") return { title: `${row.name} Priority: ranked accounts`, basis: scope, calculation: `Add the three purchase-count categories: ${row.zero} + ${row.withPurchases} + ${row.unavailable} = ${row.total}.`, note: "This counts ranked accounts, not Sales Invoices." };
  if (measure === "zero") return { title: `${row.name} Priority: zero recorded purchases`, basis: `${scope} These ${row.zero} accounts have a saved count of exactly zero valid Sales Invoices in the previous 24 months.`, calculation: "Count ranked accounts whose saved 24-month frequency is 0.", note: "Zero recorded purchases does not confirm inactivity, no ongoing projects, or account closure." };
  if (measure === "withPurchases") return { title: `${row.name} Priority: at least one purchase`, basis: `${scope} These ${row.withPurchases} accounts have one or more valid Sales Invoices in the previous 24 months.`, calculation: "Count ranked accounts whose saved 24-month frequency is greater than 0. An account is counted once, regardless of its invoice count." };
  if (measure === "unavailable") return { title: `${row.name} Priority: count unavailable`, basis: `${scope} These ${row.unavailable} accounts have no usable saved 24-month frequency count.`, calculation: `${row.total} ranked accounts - ${row.zero} with zero - ${row.withPurchases} with purchases = ${row.unavailable} unavailable.`, note: "An unavailable count is not treated as zero." };
  return { title: `${row.name} Priority: zero-purchase share`, basis: `${scope} ${counts}`, calculation: row.total ? `${row.zero} ${row.zero === 1 ? "account" : "accounts"} with zero purchases / ${row.total} ranked accounts x 100 = ${pct(row.zero / row.total)}.` : "No ranked accounts match, so a percentage cannot be calculated.", note: "Accounts with an unavailable count remain in the total. This percentage describes recorded purchases only, not account activity or closure." };
}
const money = new Intl.NumberFormat("en-PH", { style: "currency", currency: "PHP", minimumFractionDigits: 2, maximumFractionDigits: 2 });
const number = new Intl.NumberFormat("en-PH");
const pct = (value: number | null | undefined) => value == null ? "Unavailable" : `${(value * 100).toFixed(2)}%`;
const score = (value: number | null | undefined) => value == null ? "Unavailable" : value.toFixed(4);
const finiteValue = (value: unknown): number | null => value == null || value === "" || !Number.isFinite(Number(value)) ? null : Number(value);
const evidenceScore = (value: unknown) => value == null || !Number.isFinite(Number(value)) ? "Unavailable" : score(Number(value));
const evidencePct = (value: unknown) => value == null || !Number.isFinite(Number(value)) ? "Unavailable" : pct(Number(value));

const chartContext: Record<string, string> = {
  "Annual Valid Sales Invoice Sales": "Each year covers accepted invoices from the source files. The height is their total peso value, shown in millions. Account filters do not change this baseline.",
  "Yearly Transacting B2B Accounts": "For each complete year, the height counts distinct client-verified business accounts with at least one accepted invoice. It is not a count of invoices.",
  "Priority Group Counts": "Each bar counts the active, verified accounts in one saved review group after the page filters. Filtering does not recalculate their groups.",
  "Top 10 Ranked Accounts": "Each bar is an account's saved score, from 0 to 1; its name appears at the left. Accounts are shown in published rank order, not by predicted sales.",
  "RFM Score Distribution": "The horizontal labels are 1-to-5 scores for past buying activity. Each bar counts verified business accounts at that score for the named measure. An account appears once per measure.",
  "Historical Settlement Duration Distribution": "Each horizontal interval groups accounts by their average days from invoice to final valid payment. The bar height counts accounts with enough payment evidence.",
  "Published CRITIC Criterion Weights": "Each bar is the saved share assigned to Recency, Frequency, Monetary, or Settlement in the priority formula. The four shares add to 100%; page filters do not recalculate them.",
  "Prediction Horizon Comparison": "Each label is a future window tested on past data. Bar heights show model-check scores from 0 to 1; higher means better past test performance, not a guarantee for a new forecast.",
  "Model Benchmark: Mean Macro F1": "Each bar is a candidate model tested on past years. Its height averages that model's two-class performance score across the test years, giving each year equal weight.",
  "Sensitivity: Mean Spearman Rank Correlation": "Each horizontal label is the allowed change to saved priority weights. The lines show how similar the resulting account order stayed to the published order; 1 means identical order.",
  "Historical Backtests: Lift vs Random": "Each year is a past test date. Bar height compares the selected accounts' next-year sales-value share with the share expected by selecting the same number at random; 1 is the comparison baseline.",
};

function RunContext({ run, onRefresh }: { run: RunSummary; onRefresh: () => void }) {
  return <div className="report-meta" aria-label="Published analysis context">
    <span>Analysis reference <strong><ResultValue metric="reference">{run.analysis_reference_date ?? "Unavailable"}</ResultValue></strong></span>
    <span>Published run <strong className="mono"><ResultValue metric="run">{run.analysis_run_id.slice(0, 12)}</ResultValue></strong></span>
    <span>Completed <strong><ResultValue metric="run">{run.completed_at ? new Date(run.completed_at).toLocaleString() : "Unavailable"}</ResultValue></strong></span>
    <span>Model <strong><ResultValue metric="model">{run.model_version ?? "Unavailable"}</ResultValue></strong></span>
    <button type="button" className="button secondary" onClick={onRefresh}><RefreshCw size={15} />Refresh reports</button>
  </div>;
}

function ChartFrame({ id, title, description, children, tall = false, empty = false, xLabel, yLabel, caption }: { id?: ReportSection; title: string; description: string; children: React.ReactNode; tall?: boolean; empty?: boolean; xLabel?: string; yLabel?: string; caption?: string }) {
  return <section id={id} tabIndex={id ? -1 : undefined} className="native-chart insight-target" aria-label={title}>
    <div className="native-chart-heading"><h3><ResultValue metric={title.includes("Priority Score") ? "fps" : title.includes("CRITIC") ? "weight" : title.includes("RFM") ? "rfm_score" : title.includes("Settlement") ? "settlement" : title.includes("Spearman") ? "spearman" : title.includes("Lift") ? "lift" : title.includes("Prediction Horizon") ? "horizon" : title.includes("Model Benchmark") ? "benchmark" : title.includes("Priority Group") ? "group_count" : title.includes("Sales Invoice Sales") ? "sales" : "count"}>{title}</ResultValue></h3><p>{description}</p></div>
    {empty ? <div className="native-chart-empty" role="status">No published evidence is available for this chart in the selected run.</div> : <div className={`native-chart-canvas${tall ? " tall" : ""}`} role="group" aria-label={`${title}. ${description}`}>{children}</div>}
    {(xLabel || yLabel) && <div className="native-chart-axes"><span><b>Horizontal (X):</b> {xLabel}</span><span><b>Vertical (Y):</b> {yLabel}</span>{(chartContext[title] ?? (title.startsWith("Historical Backtests ") ? chartContext["Historical Backtests: Lift vs Random"] : undefined)) && <span className="native-chart-axis-context">{chartContext[title] ?? chartContext["Historical Backtests: Lift vs Random"]}</span>}</div>}
    {caption && <p className="native-chart-caption">{caption}</p>}
  </section>;
}

function ChartResultTooltip({ active, payload, label, detail, format = value => String(value), labelPrefix = "" }: {
  active?: boolean;
  payload?: readonly { name?: string; value?: number | string; color?: string }[];
  label?: string | number;
  detail: string;
  format?: (value: number) => string;
  labelPrefix?: string;
}) {
  if (!active || !payload?.length) return null;
  return <div className="native-result-tooltip" role="tooltip">
    {label != null && <strong>{labelPrefix}{label}</strong>}
    {payload.map((item, index) => <div key={`${item.name ?? "value"}-${index}`}><span>{item.name ?? "Value"}</span><b>{format(Number(item.value))}</b></div>)}
    <small>{detail}</small>
  </div>;
}

function FilterSelect({ label, value, options, onChange }: { label: string; value: string; options: string[]; onChange: (value: string) => void }) {
  return <label className="native-filter">{label}<select aria-label={label} value={value} onChange={event => onChange(event.target.value)}>
    <option value="">All</option>{options.map(option => <option key={option} value={option}>{option}</option>)}
  </select></label>;
}

export function ManagementOverview() {
  const { data, error, loading, reload } = useApi<Overview>("/reports/native/overview");
  const router = useRouter();
  const report = useReportState();
  const category = report.filters.business_category ?? "";
  const group = report.filters.priority_group ?? "";
  const prediction = report.filters.predicted_future_transaction_class ?? "";
  const setCategory = (value: string) => report.setFilters({ business_category: value });
  const setGroup = (value: string) => report.setFilters({ priority_group: value });
  const setPrediction = (value: string) => report.setFilters({ predicted_future_transaction_class: value });
  const overviewFilters: AccountFilters = { business_category: category, priority_group: group, predicted_future_transaction_class: prediction, eligibility: "ranked" };
  const topHref = (key: string) => accountDetailHref(key, accountsHref(overviewFilters, report.origin("top-accounts")).split("?")[1]);
  const accounts = data?.accounts ?? [];
  const categories = [...new Set(accounts.map(row => row.business_category).filter((value): value is string => Boolean(value)))].sort();
  const filtered = accounts.filter(row => (!category || row.business_category === category) && (!group || row.priority_group === group) && (!prediction || row.predicted_future_transaction_class === prediction));
  const distribution = groups.map(name => ({ name, count: accounts.filter(row => (!category || row.business_category === category) && (!prediction || row.predicted_future_transaction_class === prediction) && row.priority_group === name).length }));
  const top = filtered.filter(row => row.is_ranked && row.final_priority_score != null)
    .sort((a, b) => (a.priority_rank ?? Infinity) - (b.priority_rank ?? Infinity)).slice(0, 10)
    .map(row => ({ name: row.account, score: row.final_priority_score, rank: row.priority_rank, account_key: row.account_key }));
  const completeYears = (data?.business_baselines ?? []).filter(row => row.period_status === "Complete year");
  const latestComplete = completeYears.at(-1);
  const reset = report.reset;
  return <PageState loading={loading} error={error} onRetry={reload} empty={!data}>
    {data && <div className="native-report-content">
      <RunContext run={data.run} onRefresh={reload} />
      <div className="report-facts"><div><span>Current actionable</span><strong><ResultValue metric="actionable">{data.current_actionable_accounts}</ResultValue></strong></div><div><span>Ranked accounts</span><strong><ResultValue metric="ranked_count">{data.ranked_accounts}</ResultValue></strong></div><div><span>Ranked in view</span><strong><ResultValue metric="ranked_count">{filtered.filter(row => row.is_ranked).length}</ResultValue></strong></div></div>
      <p className="native-note">Current decision scope only. Historical identities and verified B2B profiles remain in the source record but are not all eligible for the current ranking.</p>
      <p className="native-note">{latestComplete ? `Latest complete year: ${latestComplete.year}. Valid SI sales: ${money.format(latestComplete.all_recorded_sales)}. Year-on-year change: ${latestComplete.all_sales_yoy_change_pct == null ? "Unavailable" : `${latestComplete.all_sales_yoy_change_pct.toFixed(2)}%`}.` : "No complete annual sales baseline is available."} Source coverage recorded through {data.business_baselines.at(-1)?.data_complete_through ?? "an unavailable date"}.</p>
      <div className="native-filter-bar"><FilterSelect label="Business category" value={category} options={categories} onChange={setCategory} /><FilterSelect label="Priority group" value={group} options={[...groups]} onChange={setGroup} /><FilterSelect label="Operational 12-month SI class" value={prediction} options={["With Future Sales", "With No Future Sales"]} onChange={setPrediction} /><button className="button secondary" onClick={reset}><RotateCcw size={15} />Reset filters</button></div>
      <ChartFrame title="Annual Valid Sales Invoice Sales" description="Accepted logical Sales Invoices in each complete year; account filters do not change this source-wide baseline." xLabel="Year" yLabel="Total Valid Sales (PHP millions)" caption="Recorded sales are not collected cash. This trend does not establish what caused sales changes." empty={!completeYears.length}>
        <ResponsiveContainer width="100%" height="100%"><LineChart data={completeYears} margin={{ top: 12, right: 24, bottom: 12, left: 20 }}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="year" /><YAxis width={64} tickFormatter={value => `${(Number(value) / 1000000).toFixed(0)}m`} /><Tooltip content={<ChartResultTooltip labelPrefix="Year " format={value => money.format(value)} detail="Add valid Sales Invoice amounts for this full year. Each invoice is counted once, even if it has several payment rows." />} /><Line type="monotone" dataKey="all_recorded_sales" name="Valid SI sales (PHP)" stroke={colors.line} strokeWidth={3} dot /></LineChart></ResponsiveContainer>
      </ChartFrame>
      <ChartFrame title="Yearly Transacting B2B Accounts" description="Distinct verified B2B accounts with at least one accepted Sales Invoice in each complete year." xLabel="Year" yLabel="Number of distinct B2B accounts" caption="A count of recorded purchasing accounts, not proof that other accounts closed or lacked projects." empty={!completeYears.length}>
        <ResponsiveContainer width="100%" height="100%"><BarChart data={completeYears}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="year" /><YAxis allowDecimals={false} /><Tooltip content={<ChartResultTooltip labelPrefix="Year " format={value => number.format(value)} detail="Count different verified business customers with at least one valid Sales Invoice in this full year." />} /><Bar dataKey="b2b_transacting_account_count" name="Transacting B2B accounts" fill={colors.medium} /></BarChart></ResponsiveContainer>
      </ChartFrame>
      <p className="native-note">The current reference year is labeled complete only when the published baseline marks it as a complete year. {data.business_baselines.at(-1)?.period_status ?? "Coverage unavailable"}.</p>
      <div className="native-chart-grid">
        <ChartFrame id="priority-distribution" title="Priority Group Counts" description="Published groups for currently actionable, ranked accounts in this view; select a bar to filter." xLabel="Priority Group" yLabel="Number of ranked accounts" caption="Groups are relative review order, not predicted purchase probability." empty={!accounts.length}><ResponsiveContainer width="100%" height="100%"><BarChart data={distribution}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="name" /><YAxis allowDecimals={false} /><Tooltip content={<ChartResultTooltip format={value => `${number.format(value)} accounts`} detail="Count ranked accounts in this review group and current view. The saved score order sets each group; the Future Sales prediction does not." />} /><Bar dataKey="count" name="Accounts" onClick={entry => setGroup(String(entry?.payload?.name ?? ""))}>{distribution.map(row => <Cell key={row.name} fill={colors[row.name.toLowerCase() as keyof typeof colors]} fillOpacity={!group || group === row.name ? 1 : 0.4} />)}</Bar></BarChart></ResponsiveContainer></ChartFrame>
        <ChartFrame id="top-accounts" title="Top 10 Ranked Accounts" description="Published Final Priority Score and analytical rank; select an account for its evidence." xLabel="Final Priority Score (0-1)" yLabel="Ranked account" caption="This is a recommended review order, not a guaranteed sales opportunity." empty={!top.length} tall><ResponsiveContainer width="100%" height="100%"><BarChart data={top} layout="vertical" margin={{ left: 16, right: 22 }}><CartesianGrid strokeDasharray="3 3" /><XAxis type="number" domain={[0, 1]} /><YAxis type="category" dataKey="name" width={150} tick={{ fontSize: 10 }} /><Tooltip content={<ChartResultTooltip format={value => score(value)} detail="FPS = sum of four normalized Recency, Frequency, Monetary, and Settlement values multiplied by published CRITIC weights. Open the account for its exact terms." />} /><Bar dataKey="score" name="Final Priority Score" fill={colors.medium} onClick={entry => { if (entry?.payload?.account_key) router.push(topHref(String(entry.payload.account_key))); }} /></BarChart></ResponsiveContainer></ChartFrame>
      </div>
      {group && <Link className="button secondary" href={accountsHref(overviewFilters, report.origin("priority-distribution"))}>Review selected Priority Group</Link>}
      <details className="native-evidence-details"><summary>Open a top account by name</summary><div className="native-account-links">{top.map(row => <Link key={row.account_key} href={topHref(row.account_key)}>#{row.rank} {row.name} <strong>{score(row.score)}</strong></Link>)}</div></details>
    </div>}
  </PageState>;
}

const settlementBins = ["Below 30", "30-<60", "60-<90", "90-<120", "120+"];
function settlementBin(days: number) { return days < 30 ? settlementBins[0] : days < 60 ? settlementBins[1] : days < 90 ? settlementBins[2] : days < 120 ? settlementBins[3] : settlementBins[4]; }

export function AccountInsights() {
  const { data, error, loading, reload } = useApi<Insights>("/reports/native/insights");
  const report = useReportState();
  const f = report.filters;
  const category = f.business_category ?? "", type = f.primary_business_type ?? "", group = f.priority_group ?? "";
  const status = f.account_status ?? "", ranking = f.eligibility === "ranked" ? "Ranked" : f.eligibility === "not_ranked" ? "Not ranked" : "";
  const prediction = f.predicted_future_transaction_class ?? "", scoreComponent = f.rfm_component ?? "";
  const scoreSelection = f.rfm_score ? Number(f.rfm_score) : null, binSelection = f.settlement_range ?? "";
  const setCategory = (value: string) => report.setFilters({ business_category: value });
  const setType = (value: string) => report.setFilters({ primary_business_type: value });
  const setGroup = (value: string) => report.setFilters({ priority_group: value });
  const setStatus = (value: string) => report.setFilters({ account_status: value });
  const setRanking = (value: string) => report.setFilters({ eligibility: value === "Ranked" ? "ranked" : value === "Not ranked" ? "not_ranked" : "all" });
  const setPrediction = (value: string) => report.setFilters({ predicted_future_transaction_class: value });
  const setScoreComponent = (value: string) => report.setFilters({ rfm_component: value });
  const setScoreSelection = (value: number | null) => report.setFilters({ rfm_score: value == null ? "" : String(value) });
  const setBinSelection = (value: string) => report.setFilters({ settlement_range: value });
  const accounts = data?.accounts ?? [];
  const option = (field: "business_category" | "primary_business_type" | "account_status") => [...new Set(accounts.filter(row => field !== "primary_business_type" || !category || row.business_category === category).map(row => row[field]).filter((value): value is string => Boolean(value)))].sort();
  const filtered = accounts.filter(row => (!category || row.business_category === category) && (!type || row.primary_business_type === type) && (!group || row.priority_group === group) && (!status || row.account_status === status) && (!ranking || (ranking === "Ranked" ? row.is_ranked : !row.is_ranked)) && (!prediction || row.predicted_future_transaction_class === prediction));
  const globalFilters: AccountFilters = { ...f, rfm_component: "", rfm_score: "", settlement_range: "", eligibility: f.eligibility || "all" };
  const drillFilters: AccountFilters = { ...globalFilters, rfm_component: scoreComponent, rfm_score: f.rfm_score, settlement_range: binSelection };
  const rfmFilters: AccountFilters = { ...globalFilters, rfm_component: scoreComponent, rfm_score: f.rfm_score };
  const settlementFilters: AccountFilters = { ...globalFilters, settlement_range: binSelection };
  const rfm = [1, 2, 3, 4, 5].map(value => ({ name: String(value), value, Recency: filtered.filter(row => row.r_score === value).length, Frequency: filtered.filter(row => row.f_score === value).length, Monetary: filtered.filter(row => row.m_score === value).length }));
  const settlement = settlementBins.map(name => ({ name, count: filtered.filter(row => row.average_settlement_days != null && settlementBin(row.average_settlement_days) === name).length }));
  const advancedCount = [type, status, ranking, prediction].filter(Boolean).length;
  const rfmMatches = filtered.filter(row => scoreSelection == null || (scoreComponent === "Recency" ? row.r_score === scoreSelection : scoreComponent === "Frequency" ? row.f_score === scoreSelection : scoreComponent === "Monetary" ? row.m_score === scoreSelection : [row.r_score, row.f_score, row.m_score].includes(scoreSelection))).length;
  const settlementMatches = filtered.filter(row => !binSelection || (row.average_settlement_days != null && settlementBin(row.average_settlement_days) === binSelection)).length;
  const purchaseActivity = groups.map(name => {
    const members = filtered.filter(row => row.is_ranked && row.priority_group === name);
    const zero = members.filter(row => row.frequency_count === 0).length;
    const withPurchases = members.filter(row => row.frequency_count != null && row.frequency_count > 0).length;
    return { name, total: members.length, zero, withPurchases, unavailable: members.length - zero - withPurchases };
  });
  const hasUnavailableActivity = purchaseActivity.some(row => row.unavailable > 0);
  const weights = ["recency", "frequency", "monetary", "settlement"].map(name => ({ name: name[0].toUpperCase() + name.slice(1), weight: data?.critic_weights?.[name] ?? null }));
  const reset = report.reset;
  return <PageState loading={loading} error={error} onRetry={reload} empty={!data}>
    {data && <div className="native-report-content"><RunContext run={data.run} onRefresh={reload} />
      <div className="native-filter-bar"><FilterSelect label="Priority group" value={group} options={[...groups]} onChange={setGroup} /><details className="account-more-filters"><summary>More Filters{advancedCount ? ` (${advancedCount} active)` : ""}</summary><div className="native-filter-bar"><FilterSelect label="Primary business type" value={type} options={option("primary_business_type")} onChange={setType} /><FilterSelect label="Current status" value={status} options={option("account_status")} onChange={setStatus} /><FilterSelect label="Ranking status" value={ranking} options={["Ranked", "Not ranked"]} onChange={setRanking} /><FilterSelect label="Future SI class" value={prediction} options={["With Future Sales", "With No Future Sales"]} onChange={setPrediction} /></div></details><button className="button secondary" onClick={reset}><RotateCcw size={15} />Reset filters</button></div>
      <ActiveFilters filters={globalFilters} count={filtered.length} defaultPopulation="all" onRemove={key => report.setFilters({ [key]: "" })} onReset={reset} />
      {!filtered.length && <p role="status">No accounts match these selections. Clear All Filters to restore the published population.</p>}
      <h2 className="report-section-title">01 - Who are our business accounts?</h2>
      <BusinessComposition rows={accounts} selectedCategory={category} onCategoryChange={setCategory} referenceDate={data.run.analysis_reference_date} filters={globalFilters} totalRanked={accounts.filter(row => row.is_ranked).length} />
      <h2 className="report-section-title">02 - How have they purchased and paid?</h2>
      <p className="native-note">Each chart keeps its original distribution for the account filters above. A selected score or duration refines only its matching-account link; it does not hide the other bars.</p>
      <div className="native-chart-grid"><section className="metric-explorer"><div className="native-filter-bar"><FilterSelect label="RFM component" value={scoreComponent} options={["Recency", "Frequency", "Monetary"]} onChange={setScoreComponent} /><FilterSelect label="RFM component score" value={scoreSelection == null ? "" : String(scoreSelection)} options={["1", "2", "3", "4", "5"]} onChange={value => setScoreSelection(value ? Number(value) : null)} /></div><ChartFrame id="rfm-distribution" title="RFM Score Distribution" description="Past buying activity, converted to saved 1-to-5 scores. Select a bar to filter accounts." xLabel="Past-activity score (1 to 5)" yLabel="Number of verified business accounts" caption="These all-history purchase-count and sales-value scores differ from the last-24-month values used in the Final Priority Score." empty={!filtered.length}><ResponsiveContainer width="100%" height="100%"><BarChart data={rfm}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="name" /><YAxis allowDecimals={false} /><Tooltip content={<ChartResultTooltip format={value => number.format(value)} detail="Number of verified business accounts at this score for the named measure. Scores compare accounts with one another; buying more recently gives a higher Recency score." />} /><Legend /><Bar dataKey="Recency" fill={colors.high} opacity={scoreSelection == null || !scoreComponent || scoreComponent === "Recency" ? 1 : .35} onClick={entry => report.setFilters({ rfm_component: "Recency", rfm_score: String(entry?.payload?.value ?? "") })}>{rfm.map(row => <Cell key={row.name} fillOpacity={scoreSelection == null || scoreSelection === row.value ? 1 : .3} />)}</Bar><Bar dataKey="Frequency" fill={colors.medium} opacity={scoreSelection == null || !scoreComponent || scoreComponent === "Frequency" ? 1 : .35} onClick={entry => report.setFilters({ rfm_component: "Frequency", rfm_score: String(entry?.payload?.value ?? "") })}>{rfm.map(row => <Cell key={row.name} fillOpacity={scoreSelection == null || scoreSelection === row.value ? 1 : .3} />)}</Bar><Bar dataKey="Monetary" fill={colors.low} opacity={scoreSelection == null || !scoreComponent || scoreComponent === "Monetary" ? 1 : .35} onClick={entry => report.setFilters({ rfm_component: "Monetary", rfm_score: String(entry?.payload?.value ?? "") })}>{rfm.map(row => <Cell key={row.name} fillOpacity={scoreSelection == null || scoreSelection === row.value ? 1 : .3} />)}</Bar></BarChart></ResponsiveContainer></ChartFrame><Link className="button secondary" href={accountsHref(rfmFilters, report.origin("rfm-distribution"))}>View accounts matching RFM selection</Link><p className="native-note">{rfmMatches} matching accounts. The complete score distribution stays visible.</p></section>
        <section className="metric-explorer"><div className="native-filter-bar"><FilterSelect label="Average settlement days" value={binSelection} options={settlementBins} onChange={setBinSelection} /></div><ChartFrame id="settlement-distribution" title="Historical Settlement Duration Distribution" description="Average days from invoice to final valid payment per account. Missing values are left out, not treated as zero." xLabel="Average days to complete collection" yLabel="Number of accounts with payment evidence" caption="This is not a measure of whether an invoice was paid late under its contract." empty={!filtered.some(row => row.average_settlement_days != null)}><ResponsiveContainer width="100%" height="100%"><BarChart data={settlement}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="name" tick={{ fontSize: 10 }} /><YAxis allowDecimals={false} /><Tooltip content={<ChartResultTooltip format={value => number.format(value)} detail="Number of accounts whose average invoice-to-final-payment time falls in this range. Accounts without a valid payment date are left out." />} /><Bar dataKey="count" name="Accounts" fill={colors.medium} onClick={entry => setBinSelection(String(entry?.payload?.name ?? ""))}>{settlement.map(row => <Cell key={row.name} fillOpacity={!binSelection || binSelection === row.name ? 1 : .3} />)}</Bar></BarChart></ResponsiveContainer></ChartFrame><Link className="button secondary" href={accountsHref(settlementFilters, report.origin("settlement-distribution"))}>View accounts matching settlement selection</Link><p className="native-note">{settlementMatches} matching accounts. Missing payment durations are never treated as zero days.</p></section></div>
      <h2 className="report-section-title">03 - Why are accounts prioritized this way?</h2>
      <ChartFrame id="priority-evidence" title="Published CRITIC Criterion Weights" description="Saved shares assigned to the four priority measures; account-view filters do not recalculate them." xLabel="Priority measure" yLabel="Share of total weight (%)" caption="These weights build the Final Priority Score; they are not CatBoost prediction factors." empty={weights.some(row => row.weight == null)}><ResponsiveContainer width="100%" height="100%"><BarChart data={weights}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="name" /><YAxis domain={[0, 1]} tickFormatter={value => `${Math.round(Number(value) * 100)}%`} /><Tooltip content={<ChartResultTooltip format={value => pct(value)} detail="The method measures how much this factor varies and how different it is from the other three, then divides that amount by the total for all four factors." />} /><Bar dataKey="weight" name="CRITIC weight" fill={colors.high} /></BarChart></ResponsiveContainer></ChartFrame>
      <section className="native-table-section" aria-label="Recent Purchase Activity by Priority Group"><div className="section-heading"><h2>Recent Purchase Activity by Priority Group</h2></div>
        <p className="native-note">Ranked accounts matching the current filters, using saved valid Sales Invoice counts for the 24 months ending at the published analysis reference date ({data.run.analysis_reference_date ?? "unavailable"}). Zero recorded purchases does not confirm inactivity, no ongoing projects, or account closure.</p>
        <div className="table-wrap"><table><thead><tr><th>Priority group</th><th>Ranked accounts</th><th>Zero valid SIs</th><th>At least one valid SI</th>{hasUnavailableActivity && <th>Count unavailable</th>}<th>Zero-purchase share</th></tr></thead><tbody>{purchaseActivity.map(row => <tr key={row.name}><th scope="row">{row.name}</th><td><ExplainedValue explanation={purchaseActivityExplanation(row, "total", data.run.analysis_reference_date)}>{number.format(row.total)}</ExplainedValue></td><td><ExplainedValue explanation={purchaseActivityExplanation(row, "zero", data.run.analysis_reference_date)}>{number.format(row.zero)}</ExplainedValue></td><td><ExplainedValue explanation={purchaseActivityExplanation(row, "withPurchases", data.run.analysis_reference_date)}>{number.format(row.withPurchases)}</ExplainedValue></td>{hasUnavailableActivity && <td><ExplainedValue explanation={purchaseActivityExplanation(row, "unavailable", data.run.analysis_reference_date)}>{number.format(row.unavailable)}</ExplainedValue></td>}<td><ExplainedValue explanation={purchaseActivityExplanation(row, "share", data.run.analysis_reference_date)}>{row.total ? pct(row.zero / row.total) : "Not applicable"}</ExplainedValue></td></tr>)}</tbody></table></div>
      </section>
      <h2 className="report-section-title">04 - What should management review next?</h2><Link className="button secondary" href={accountsHref(drillFilters, report.origin("priority-evidence"))}>Review matching accounts in Account Prioritization</Link>
      <p className="native-note">Settlement duration is historical evidence, not a contractual late/on-time assessment. Predicted class is separate from the Final Priority Score.</p>
    </div>}
  </PageState>;
}

export function AnalyticsValidation() {
  const { data, error, loading, reload } = useApi<Validation>("/reports/native/validation");
  const horizon = (data?.horizons ?? []).map(row => ({ name: `${row.horizon_months} months`, macroF1: finiteValue(row.mean_macro_f1_2020_2022), recall: finiteValue(row.mean_future_recall_2020_2022), selected: row.stage4_decision === "SELECTED" }));
  const benchmark = (data?.benchmarks ?? []).filter(row => row.source_member === "model_benchmark.csv" && ["CatBoost", "Extra Trees", "HistGradientBoosting"].includes(String(row.family))).map(row => ({ name: String(row.family), macroF1: finiteValue(row.mean_macro_f1), row }));
  const benchmarkRows = benchmark.filter(row => ["CatBoost", "Extra Trees"].includes(row.name));
  const canonical = (data?.benchmarks ?? []).filter(row => row.source_member === "model_benchmark.csv").sort((a, b) => Number(a.rank) - Number(b.rank));
  const sensitivity = (data?.sensitivity ?? []).map(row => ({ name: `+/-${Math.round(row.weight_range * 100)}%`, mean: row.mean_spearman, min: row.min_spearman, ...row }));
  const backtest = (data?.backtest.cutoffs ?? []).map(row => ({ name: row.cutoff_date.slice(0, 4), lift: row.lift_over_expected_random, ...row }));
  const studyCounts = data?.study.class_counts ?? {};
  const currentComparisons = (data?.supplemental ?? []).filter(row => String(row.source_member).endsWith("/current_metrics.csv"));
  const robustnessBacktests = (data?.supplemental ?? []).filter(row => String(row.source_member).endsWith("/backtest_summary.csv"));
  const criterionRemoval = (data?.supplemental ?? []).filter(row => String(row.source_member).endsWith("/criterion_ablation_current.csv"));
  const historicalCriterionRemoval = (data?.supplemental ?? []).filter(row => String(row.source_member).endsWith("/criterion_ablation_history.csv"));
  const boundaryChanges = (data?.supplemental ?? []).filter(row => String(row.source_member).endsWith("/boundary_movement.csv") && Number(row.group_change_count) > 0)
    .sort((a, b) => Number(b.group_change_rate) - Number(a.group_change_rate));
  return <PageState loading={loading} error={error} onRetry={reload} empty={!data}>
    {data && <div id="validation-findings" tabIndex={-1} className="native-report-content insight-target"><RunContext run={data.run} onRefresh={reload} />
      <details className="native-evidence-details"><summary>Study context and model provenance</summary>
      <div className="report-facts"><div><span>Selected model</span><strong><ResultValue metric="prediction">{data.study.model_family ?? data.run.model_version ?? "Unavailable"}</ResultValue></strong></div><div><span>Study predicted Future SI</span><strong><ResultValue metric="prediction">{studyCounts["With Future Sales"] ?? "Unavailable"}</ResultValue></strong></div><div><span>Study predicted No Future SI</span><strong><ResultValue metric="prediction">{studyCounts["With No Future Sales"] ?? "Unavailable"}</ResultValue></strong></div><div><span>Total study predictions</span><strong><ResultValue metric="count">{Object.keys(studyCounts).length ? Object.values(studyCounts).reduce((total, count) => total + count, 0) : "Unavailable"}</ResultValue></strong></div><div><span>Current ranked</span><strong><ResultValue metric="ranked_count">{data.ranked_account_count}</ResultValue></strong></div><div><span>Sensitivity scenarios</span><strong><ResultValue metric="scenarios">{data.sensitivity.length ? data.sensitivity.reduce((total, row) => total + row.iterations, 0) : "Unavailable"}</ResultValue></strong></div><div><span>Account-scenario rows</span><strong><ResultValue metric="scenarios">{data.sensitivity.length ? number.format(data.scenario_detail_count) : "Unavailable"}</ResultValue></strong></div><div><span>Study outcome monitoring</span><strong><ResultValue metric="prediction">{data.study.status === "Validated" ? data.study.monitoring_status ?? "Pending" : "Unavailable"}</ResultValue></strong></div></div>
      <p className="native-note">Study origin {data.study.forecast_origin ?? "unavailable"}; {data.study.target_horizon_months ?? "unavailable"}-month outcome window {data.study.future_window_start ?? "unavailable"} to {data.study.future_window_end ?? "unavailable"}. Predictions are not verified future sales. Model evidence: {data.model_evidence_status}. Artifact SHA-256: <code>{data.model_artifact_hash ?? "Unavailable"}</code>.</p>
      </details>
      <section className="validation-group" aria-label="Predictive Validation"><h2>Predictive Validation</h2><p className="native-note">How well did the classifier distinguish future purchases in completed historical tests? The current forecast requires its own verified outcome evidence.</p><div className="validation-finding"><h3>Historical classifier finding</h3><p>Saved CatBoost mean chronological Macro F1: <ResultValue metric="macro_f1">{evidenceScore(benchmark.find(row => row.name === "CatBoost")?.row.mean_macro_f1)}</ResultValue>. This gives both sales classes equal importance across completed historical evaluation years. It is not the realized accuracy of the pending study forecast.</p><p>Study classifications: {studyCounts["With Future Sales"] ?? "Unavailable"} With Future Sales and {studyCounts["With No Future Sales"] ?? "Unavailable"} With No Future Sales. Neither class changes account priority.</p></div>
      <details className="native-evidence-details"><summary>Model selection and historical classification evidence</summary><div className="native-report-content">
      <section className="native-table-section"><div className="section-heading"><h2>Predictive model evaluation</h2></div><p className="native-note">The frozen CatBoost classifier asks whether an account has at least one valid Sales Invoice in the next 12 months. Its development data have unequal classes. Macro F1 gives both classes equal importance when summarizing classification quality; balanced class weights do not turn the underlying observations into a 50/50 sample.</p></section>
      <section className="native-table-section"><div className="section-heading"><h2>Development observations by cutoff year</h2></div>{data.development_profile.length ? <><div className="table-wrap"><table><thead><tr><th>Cutoff year</th><th>Account-cutoff observations</th><th>With Future Sales</th><th>With No Future Sales</th><th>Future-sales share</th></tr></thead><tbody>{data.development_profile.map(row => <tr key={String(row.cutoff_year)}><td>{row.cutoff_year}</td><td><ResultValue metric="count">{row.observations}</ResultValue></td><td><ResultValue metric="count">{row.future_transaction}</ResultValue></td><td><ResultValue metric="count">{row.no_future_transaction}</ResultValue></td><td><ResultValue metric="share">{evidencePct(row.future_transaction_share)}</ResultValue></td></tr>)}</tbody></table></div><p className="native-note">These are repeated account-cutoff observations from 2018-2022, not distinct companies. The recorded development total is <ResultValue metric="count">{data.development_profile.reduce((sum, row) => sum + Number(row.observations), 0)}</ResultValue> observations.</p></> : <p className="native-note">Development class evidence is unavailable for this registered model.</p>}</section>
      <div className="native-chart-grid"><ChartFrame title="Prediction Horizon Comparison" description="Historical 3-, 6-, and 12-month target screening used the same Extra Trees learner; 12 months was retained before CatBoost model selection." xLabel="Outcome horizon" yLabel="Mean validation score (0-1)" caption="This screens outcome-window length, not CatBoost's pending 2026 accuracy or an active Extra Trees deployment." empty={!horizon.length}><ResponsiveContainer width="100%" height="100%"><BarChart data={horizon}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="name" /><YAxis domain={[0, 1]} /><Tooltip content={<ChartResultTooltip format={value => score(value)} detail="Historical labelled validation: Macro F1 averages both class F1 scores; Future recall is true Future divided by true Future plus missed Future. This is target-horizon screening, not active Extra Trees scoring." />} /><Legend /><Bar dataKey="macroF1" name="Macro F1" fill={colors.high} /><Bar dataKey="recall" name="Future recall" fill={colors.medium} /></BarChart></ResponsiveContainer></ChartFrame>
        <ChartFrame title="Model Benchmark: Mean Macro F1" description="Chronological equal-year comparison; CatBoost selected, Extra Trees retained as challenger." xLabel="Model family" yLabel="Mean Macro F1 (0-1)" caption="Small benchmark differences should not be treated as proof of future superiority." empty={!benchmark.length}><ResponsiveContainer width="100%" height="100%"><BarChart data={benchmark}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="name" tick={{ fontSize: 10 }} /><YAxis domain={[0, 1]} /><Tooltip content={<ChartResultTooltip format={value => score(value)} detail="Mean of chronological evaluation-year Macro F1 values, giving each year equal weight. Each year's Macro F1 averages the two class F1 scores." />} /><Bar dataKey="macroF1" name="Mean Macro F1">{benchmark.map(row => <Cell key={row.name} fill={row.name === "CatBoost" ? colors.high : colors.medium} />)}</Bar></BarChart></ResponsiveContainer></ChartFrame></div>
      <section className="native-table-section"><div className="section-heading"><h2>Selected model and challenger</h2></div><div className="table-wrap"><table><thead><tr><th>Metric</th>{benchmarkRows.map(row => <th key={row.name}>{row.name}</th>)}</tr></thead><tbody>{([ ["Mean Macro F1", "mean_macro_f1", "macro_f1"], ["Mean error", "mean_classification_error", "error"], ["Balanced accuracy", "mean_balanced_accuracy", "balanced_accuracy"], ["Future recall", "mean_future_recall", "recall"], ["Future F1", "mean_future_f1", "f1"], ["MCC", "mean_mcc", "mcc"] ] as const).map(([label, key, metric]) => <tr key={key}><th>{label}</th>{benchmarkRows.map(row => <td key={row.name}><ResultValue metric={metric}>{evidenceScore(row.row[key])}</ResultValue></td>)}</tr>)}</tbody></table></div></section>
      <section className="native-table-section"><div className="section-heading"><h2>CatBoost chronological evaluation, 2020-2022</h2></div>{data.yearly_folds.length ? <div className="table-wrap"><table><thead><tr><th>Evaluation year</th><th>Macro F1</th><th>Classification error</th><th>Balanced accuracy</th><th>Future recall</th><th>Missed Future</th><th>False Future</th></tr></thead><tbody>{data.yearly_folds.map(row => <tr key={String(row.outer_year)}><td>{row.outer_year}</td><td><ResultValue metric="macro_f1">{evidenceScore(row.macro_f1)}</ResultValue></td><td><ResultValue metric="error">{evidencePct(row.classification_error)}</ResultValue></td><td><ResultValue metric="balanced_accuracy">{evidenceScore(row.balanced_accuracy)}</ResultValue></td><td><ResultValue metric="recall">{evidencePct(row.future_recall)}</ResultValue></td><td><ResultValue metric="count">{row.cm_fn}</ResultValue></td><td><ResultValue metric="count">{row.cm_nf}</ResultValue></td></tr>)}</tbody></table></div> : <p className="native-note">Per-year model evidence is unavailable for this registered model.</p>}<p className="native-note">Each row evaluates a later calendar cutoff than the model training data. These retrospective results do not establish 2026 realized accuracy.</p></section>
      <details className="native-evidence-details"><summary>Canonical classifier benchmark ({canonical.length} models)</summary><div className="table-wrap"><table><thead><tr><th>Rank</th><th>Model family</th><th>Mean Macro F1</th><th>Mean error</th><th>Future recall</th></tr></thead><tbody>{canonical.map(row => <tr key={String(row.family)}><td><ResultValue metric="model_rank">{row.rank}</ResultValue></td><td>{row.family}</td><td><ResultValue metric="macro_f1">{evidenceScore(row.mean_macro_f1)}</ResultValue></td><td><ResultValue metric="error">{evidencePct(row.mean_classification_error)}</ResultValue></td><td><ResultValue metric="recall">{evidencePct(row.mean_future_recall)}</ResultValue></td></tr>)}</tbody></table></div><p className="native-note">The canonical comparison comprises 21 classifiers and a Majority Baseline. A small mean-score difference does not establish a large practical advantage.</p></details>
      <section className="native-table-section"><div className="section-heading"><h2>Historical lookback comparison</h2></div><div className="table-wrap"><table><thead><tr><th>Lookback</th><th>Mean Macro F1</th><th>Mean error</th><th>Balanced accuracy</th><th>Future-class F1</th></tr></thead><tbody>{data.lookback_summary.map(row => <tr key={String(row.lookback_months)}><td><ResultValue metric="lookback">{row.lookback_months} months</ResultValue></td><td><ResultValue metric="macro_f1">{evidenceScore(row.mean_macro_f1)}</ResultValue></td><td><ResultValue metric="error">{evidencePct(row.mean_error)}</ResultValue></td><td><ResultValue metric="balanced_accuracy">{evidenceScore(row.mean_balanced_accuracy)}</ResultValue></td><td><ResultValue metric="f1">{evidenceScore(row.mean_future_f1)}</ResultValue></td></tr>)}</tbody></table></div><p className="native-note">The lookback comparison tests how far back historical features reach. It is distinct from the 3/6/12-month future outcome horizon.</p></section>
      <p className="native-note">CatBoost was selected on recorded mean chronological Macro F1; its advantage over Extra Trees is small. {data.historical_error_summary ? ("Historical pooled validation recorded " + data.historical_error_summary.errors + " errors in " + data.historical_error_summary.observations + " observations (" + data.historical_error_summary.true_future + " true Future, " + data.historical_error_summary.missed_future + " missed Future, " + data.historical_error_summary.true_no_future + " true No Future, " + data.historical_error_summary.false_future + " false Future).") : "Pooled confusion evidence is unavailable."} This is not confirmed 2026 forecast accuracy.</p>
      <section className="native-table-section"><div className="section-heading"><h2>Historical later-period confirmations</h2></div><div className="table-wrap"><table><thead><tr><th>Period</th><th>Cutoff</th><th>Outcome end</th><th>Accounts</th><th>Actual Future / No Future</th><th>Predicted Future / No Future</th><th>Error</th><th>Macro F1</th><th>Accuracy</th></tr></thead><tbody>{data.later_checks.map(row => <tr key={String(row.cutoff_date)}><td>{row.period}</td><td>{row.cutoff_date}</td><td>{row.future_window_end}</td><td><ResultValue metric="count">{row.observations}</ResultValue></td><td><ResultValue metric="count">{row.actual_future_transaction} / {row.actual_no_future_transaction}</ResultValue></td><td><ResultValue metric="prediction">{row.predicted_future_transaction} / {row.predicted_no_future_transaction}</ResultValue></td><td><ResultValue metric="error">{evidencePct(row.classification_error)}</ResultValue></td><td><ResultValue metric="macro_f1">{evidenceScore(row.macro_f1)}</ResultValue></td><td><ResultValue metric="accuracy">{evidencePct(row.accuracy)}</ResultValue></td></tr>)}</tbody></table></div><p className="native-note">These are historical outcome confirmations, not accuracy claims for the pending 2026 forecast.</p></section>
      <AdditionalValidation branch="predictive" evidence={data.additional_evidence ?? {}} referenceDate={String(data.additional_evidence?.annual_rank_stability?.[0]?.study_reference_date ?? "") || null} />
      </div></details></section>
      <section className="validation-group" aria-label="Prescriptive Validation"><h2>Prescriptive Validation</h2><p className="native-note">How stable is the four-factor review order, and what happened in historical follow-up periods? These checks describe evidence and uncertainty, not guaranteed sales.</p><div className="validation-finding"><h3>Weight-sensitivity and historical backtesting</h3><p>{sensitivity.length ? `${sensitivity.reduce((sum, row) => sum + row.iterations, 0)} saved weight-change scenarios; mean rank agreement ranges from ${score(Math.min(...sensitivity.map(row => row.mean)))} to ${score(Math.max(...sensitivity.map(row => row.mean)))}.` : "Sensitivity evidence is unavailable."} {backtest.length} completed historical backtests are retained below. Alternative weighting and aggregation checks remain supplementary; they do not replace CRITIC plus additive MCS.</p></div>
      <AdditionalValidation branch="prescriptive" evidence={data.additional_evidence ?? {}} referenceDate={String(data.additional_evidence?.annual_rank_stability?.[0]?.study_reference_date ?? "") || null} />
      <details className="native-evidence-details"><summary>Weight sensitivity, backtests, and technical robustness</summary><div className="native-report-content">
      <section className="native-table-section"><div className="section-heading"><h2>Prescriptive robustness and historical usefulness</h2></div><p className="native-note">CRITIC derives criterion weights from the eligible account data. Additive MCS combines the four normalized criteria into Final Priority Score. The predicted Future Sales class does not contribute to the score.</p><div className="table-wrap"><table><thead><tr><th>Criterion</th><th>Published run weight</th></tr></thead><tbody>{["recency", "frequency", "monetary", "settlement"].map(key => <tr key={key}><td>{key[0].toUpperCase() + key.slice(1)}</td><td><ResultValue metric="weight">{pct(data.critic_weights[key])}</ResultValue></td></tr>)}</tbody></table></div></section>
      <div className="native-chart-grid"><ChartFrame title="Sensitivity: Mean Spearman Rank Correlation" description="Persisted CRITIC-weight perturbation summaries; no simulation runs in the browser." xLabel="Weight perturbation range" yLabel="Spearman rank correlation (0-1)" caption="High rank correlation describes stability under these tested perturbations, not certainty about future sales." empty={!sensitivity.length}><ResponsiveContainer width="100%" height="100%"><LineChart data={sensitivity}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="name" /><YAxis domain={[0, 1]} /><Tooltip content={<ChartResultTooltip format={value => score(value)} detail="Spearman compares published baseline account ranks with ranks after the named CRITIC-weight perturbation. Mean and minimum summarize the recorded scenarios." />} /><Legend /><Line dataKey="mean" name="Mean Spearman" stroke={colors.high} strokeWidth={2} /><Line dataKey="min" name="Minimum Spearman" stroke={colors.medium} strokeWidth={2} /></LineChart></ResponsiveContainer></ChartFrame>
        <ChartFrame title={backtest.length ? `Historical Backtests ${backtest[0].name}-${backtest[backtest.length - 1].name}: Lift vs Random` : "Historical Backtests: Lift vs Random"} description="Published closure-aware cutoff results; the dashed line marks random-selection performance." xLabel="Historical cutoff year" yLabel="Future-sales value capture lift vs random (times)" caption="Lift above 1 means the selected accounts captured a higher share of succeeding valid Sales Invoice value than the k/n random-selection expectation. These retrospective checks do not show that follow-up caused the sales." empty={!backtest.length}><ResponsiveContainer width="100%" height="100%"><BarChart data={backtest}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="name" /><YAxis /><Tooltip content={<ChartResultTooltip format={value => `${score(value)} times`} detail="Historical lift = selected top-decile succeeding SI value share divided by the exact random-selection baseline k/n. This is retrospective association, not causal uplift." />} /><ReferenceLine y={1} stroke={colors.muted} strokeDasharray="5 4" label="Random = 1" /><Bar dataKey="lift" name="Lift vs random" fill={colors.medium} /></BarChart></ResponsiveContainer></ChartFrame></div>
      <div className="native-chart-grid"><section className="native-table-section"><div className="section-heading"><h2>Sensitivity summary</h2></div><div className="table-wrap"><table><thead><tr><th>Range</th><th>Scenarios</th><th>Mean Spearman</th><th>Max group movement</th></tr></thead><tbody>{sensitivity.map(row => <tr key={row.name}><td>{row.name}</td><td><ResultValue metric="scenarios">{row.iterations}</ResultValue></td><td><ResultValue metric="spearman">{score(row.mean)}</ResultValue></td><td><ResultValue metric="movement">{pct(row.max_group_movement_rate)}</ResultValue></td></tr>)}</tbody></table></div></section><section className="native-table-section"><div className="section-heading"><h2>Backtest summary</h2></div><div className="table-wrap"><table><thead><tr><th>Cutoff</th><th>Eligible</th><th>Selected</th><th>Random k/n</th><th>Sales value captured</th><th>Lift (times)</th></tr></thead><tbody>{backtest.map(row => <tr key={row.name}><td>{row.name}</td><td><ResultValue metric="count">{row.eligible_account_count}</ResultValue></td><td><ResultValue metric="count">{row.selected_account_count}</ResultValue></td><td><ResultValue metric="random">{pct(row.expected_random_capture)}</ResultValue></td><td><ResultValue metric="capture">{pct(row.top_decile_capture)}</ResultValue></td><td><ResultValue metric="lift">{score(row.lift_over_expected_random)}</ResultValue></td></tr>)}</tbody></table></div></section></div>
      <section className="native-table-section"><div className="section-heading"><h2>Criterion-removal checks</h2></div>{criterionRemoval.length ? <div className="table-wrap"><table><thead><tr><th>Removed criterion</th><th>Rank Spearman</th><th>Priority Group changes</th><th>Remaining weight range</th></tr></thead><tbody>{criterionRemoval.map(row => <tr key={String(row.removed_criterion)}><td>{row.removed_criterion}</td><td><ResultValue metric="spearman">{evidenceScore(row.rank_spearman)}</ResultValue></td><td><ResultValue metric="movement_count">{row.group_changes}</ResultValue></td><td><ResultValue metric="weight">{evidencePct(row.remaining_weight_min)} to {evidencePct(row.remaining_weight_max)}</ResultValue></td></tr>)}</tbody></table></div> : <p className="native-note">Criterion-removal evidence is unavailable.</p>}<p className="native-note">These are robustness checks, not alternative deployed ranking methods. Removing a criterion can materially change ranks or groups.</p></section>
      <details className="native-evidence-details"><summary>Historical criterion-removal checks ({historicalCriterionRemoval.length})</summary><div className="table-wrap"><table><thead><tr><th>Cutoff</th><th>Removed criterion</th><th>Eligible</th><th>Selected</th><th>Capture rate</th><th>Lift vs random</th></tr></thead><tbody>{historicalCriterionRemoval.map((row, index) => <tr key={index}><td>{row.cutoff}</td><td>{row.removed_criterion}</td><td><ResultValue metric="count">{row.eligible_accounts}</ResultValue></td><td><ResultValue metric="count">{row.selected_count}</ResultValue></td><td><ResultValue metric="capture">{evidencePct(row.capture_rate)}</ResultValue></td><td><ResultValue metric="lift">{evidenceScore(row.lift)}</ResultValue></td></tr>)}</tbody></table></div></details>
      <details className="native-evidence-details"><summary>Priority boundary movement observations ({boundaryChanges.length})</summary><p className="native-note">Only accounts with at least one group change across the recorded weight-perturbation scenarios are listed. A change is scenario-specific, not a new published priority assignment.</p><div className="table-wrap"><table><thead><tr><th>Range</th><th>Account</th><th>Baseline group</th><th>Group changes</th><th>Scenario change rate</th><th>Maximum rank movement</th></tr></thead><tbody>{boundaryChanges.map((row, index) => <tr key={index}><td><ResultValue metric="perturbation">{evidencePct(row.perturbation_level)}</ResultValue></td><td>{row.account_name}</td><td><ResultValue metric="group">{row.baseline_priority_group}</ResultValue></td><td><ResultValue metric="movement_count">{row.group_change_count}</ResultValue></td><td><ResultValue metric="movement">{evidencePct(row.group_change_rate)}</ResultValue></td><td><ResultValue metric="rank_movement">{row.maximum_absolute_rank_change}</ResultValue></td></tr>)}</tbody></table></div></details>
      <details className="native-evidence-details"><summary>Leave-one-account-out CRITIC influence ({data.critic_influence.length})</summary><div className="table-wrap"><table><thead><tr><th>Removed account</th><th>Maximum weight change</th><th>Rank Spearman</th><th>Group movement</th><th>Recomputed weights</th></tr></thead><tbody>{data.critic_influence.map((row, index) => <tr key={index}><td>{String(row.removed_account ?? "Unavailable")}</td><td><ResultValue metric="weight_change">{evidenceScore(row.maximum_absolute_weight_change)}</ResultValue></td><td><ResultValue metric="spearman">{evidenceScore(row.spearman_correlation)}</ResultValue></td><td><ResultValue metric="movement">{evidencePct(row.group_movement_rate)}</ResultValue></td><td><ResultValue metric="recomputed_weights"><code>{JSON.stringify(row.recomputed_weights ?? {})}</code></ResultValue></td></tr>)}</tbody></table></div></details>
      <details className="native-evidence-details"><summary>Supplementary weighting and aggregation evidence ({data.supplemental.length})</summary><div className="table-wrap"><table><thead><tr><th>Comparison</th><th>Rank Spearman</th><th>Group agreement</th><th>Group changes</th></tr></thead><tbody>{currentComparisons.map((row, index) => <tr key={index}><td>{String(row.comparison ?? (String(row.source_member).includes("AGGREGATION") ? "Additive MCS vs CRITIC-TOPSIS" : "Unavailable"))}</td><td><ResultValue metric="spearman">{evidenceScore(row.spearman)}</ResultValue></td><td><ResultValue metric="agreement">{evidencePct(row.group_agreement)}</ResultValue></td><td><ResultValue metric="movement_count">{String(row.group_changes ?? "Unavailable")}</ResultValue></td></tr>)}</tbody></table></div><div className="table-wrap"><table><thead><tr><th>Method</th><th>Periods</th><th>Lift above random</th><th>Mean lift</th><th>Minimum lift</th><th>Pooled future sales capture</th></tr></thead><tbody>{robustnessBacktests.map((row, index) => <tr key={index}><td>{String(row.method ?? "Unavailable")}</td><td><ResultValue metric="count">{String(row.periods ?? "Unavailable")}</ResultValue></td><td><ResultValue metric="count">{String(row.periods_lift_above_1 ?? "Unavailable")}</ResultValue></td><td><ResultValue metric="lift">{evidenceScore(row.mean_lift)}</ResultValue></td><td><ResultValue metric="lift">{evidenceScore(row.minimum_lift)}</ResultValue></td><td><ResultValue metric="capture">{evidencePct(row.pooled_future_sales_capture_rate)}</ResultValue></td></tr>)}</tbody></table></div></details>
      </div></details></section>
      <p className="native-note">Predictive CatBoost classification and prescriptive CRITIC + additive MCS are separate. Entropy, Equal Weighting, and TOPSIS results are locked 2025-study supplementary checks, not operational replacements or recalculations for later runs.</p>
    </div>}
  </PageState>;
}
